create table folha.parametro_fiscal (
    id_parametro      number generated always as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20 noorder
    nocycle nokeep noscale not null enable,
    dt_vigencia_ini   date not null enable,
    ded_dependente    number(10, 2) not null enable,
    desc_simplificado number(10, 2) not null enable,
    red_isencao_ate   number(10, 2) not null enable,
    red_valor_max     number(10, 2) not null enable,
    red_ate           number(10, 2) not null enable,
    red_constante     number(10, 2) not null enable,
    red_fator         number(10, 6) not null enable
);

alter table folha.parametro_fiscal
    add constraint pk_parametro_fiscal primary key ( id_parametro )
        using index enable;

alter table folha.parametro_fiscal add constraint uk_parametro_fiscal unique ( dt_vigencia_ini )
    using index enable;


